<template>
  <div class="content-page">
    <PageHeader title="模型" description="机器人用到的 AI 模型，支持任何 OpenAI 兼容接口。改完可以点“测试”确认能用。"><el-button type="primary" :icon="Plus" @click="openCreate('chat')">添加模型</el-button></PageHeader>
    <template v-for="group in groups" :key="group.kind">
      <div class="list-group-title"><h2>{{ group.title }}</h2><span>{{ group.hint }}</span></div>
      <div v-if="group.items.length" class="entity-list">
        <div v-for="model in group.items" :key="model.id" class="entity-row">
          <div class="entity-name"><span class="entity-icon" :class="model.kind === 'chat' ? 'purple' : 'green'"><el-icon><component :is="model.kind === 'chat' ? ChatDotSquare : model.kind === 'image' ? PictureIcon : Coin" /></el-icon></span><div><strong>{{ model.name }} <StatusBadge :status="model.status" /><span v-if="model.proxyId" class="pill idle proxy-pill" :title="'请求经代理发出：' + proxyName(model.proxyId)">代理 · {{ proxyName(model.proxyId) }}</span></strong><small :title="model.baseUrl">{{ model.baseUrl }}</small></div></div>
          <div class="entity-facts">
            <div><span>模型</span><strong>{{ model.model }}</strong></div>
            <div v-if="model.kind === 'chat'"><span>联网搜索 / 思考等级</span><strong>{{ searchModeText(model.webSearchMode) }} · {{ reasoningText(model.reasoningEffort) }}</strong></div>
            <div v-else-if="model.kind === 'embedding'"><span>向量维度</span><strong>{{ model.dimension || '—' }}</strong></div>
            <div><span>{{ model.kind === 'image' ? '每张价格' : '输入 / 输出单价' }}</span><strong :class="{ unset: !hasPrice(model) }">{{ priceText(model) }}</strong></div>
            <div><span>最近测试延迟</span><strong>{{ model.latency ? `${model.latency}ms` : '还没测试' }}</strong></div>
          </div>
          <div class="entity-actions"><el-button :icon="VideoPlay" @click="openWorkbench(model)">测试</el-button><el-button type="primary" plain @click="edit(model)">配置</el-button></div>
        </div>
      </div>
      <div v-else class="panel"><EmptyState mood="thinking" :title="`还没有${group.title}`" :description="group.empty"><el-button :icon="Plus" @click="openCreate(group.kind)">添加{{ group.title }}</el-button></EmptyState></div>
    </template>

    <el-dialog v-model="dialog" :title="form.id?'配置模型':'添加模型配置'" width="620px"><el-form label-position="top"><div class="form-grid"><el-form-item label="配置名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="模型类型"><el-select v-model="form.kind"><el-option label="对话模型" value="chat" /><el-option label="Embedding 模型" value="embedding" /><el-option label="生图模型" value="image" /></el-select></el-form-item></div><el-form-item label="Base URL"><el-input v-model="form.baseUrl" placeholder="例如：https://example.com/v1" /><small class="form-tip">OpenAI 兼容地址通常包含 /v1。</small></el-form-item><div class="form-grid"><el-form-item label="模型名称"><el-input v-model="form.model" /></el-form-item><el-form-item v-if="form.kind==='embedding'" label="向量维度"><el-input-number v-model="form.dimension" :min="128" :max="4096" /></el-form-item><el-form-item v-else-if="form.kind==='chat'" label="思考等级"><el-select v-model="form.reasoningEffort"><el-option label="模型默认" value="default" /><el-option label="关闭（none）" value="none" /><el-option label="最小（minimal）" value="minimal" /><el-option label="低（low）" value="low" /><el-option label="中（medium）" value="medium" /><el-option label="高（high）" value="high" /></el-select><small class="form-tip">仅支持推理等级的模型会生效；不确定时使用“模型默认”。</small></el-form-item></div><el-form-item label="网络"><el-select v-model="proxyChoice"><el-option label="直连（不走代理）" value="direct" /><el-option v-for="p in proxies" :key="p.id" :label="p.name" :value="p.id"><span>{{ p.name }}</span><small class="option-sub mono">{{ p.address }}</small></el-option></el-select><small class="form-tip">海外模型直连访问不了时选择代理。<el-button link type="primary" size="small" @click="$router.push('/system')">{{ proxies.length ? '管理代理' : '还没有代理，去系统状态添加' }}</el-button></small></el-form-item><el-form-item label="API Key"><el-input v-model="apiKey" type="password" show-password :placeholder="form.id?'留空则不覆盖现有密钥':'请输入 API Key'" /><small class="form-tip">密钥保存后仅展示脱敏值。</small></el-form-item><el-form-item v-if="form.kind==='image'" label="每张价格（元）" class="price-item"><el-input-number v-model="form.pricePerImage" :min="0" :precision="4" :step="0.01" :controls="false" placeholder="未设置" class="price-single" /><small class="form-tip">每成功生成一张图按这个价格计入成本。</small></el-form-item><el-form-item v-else label="价格（元 / 百万 token）" class="price-item"><div class="price-grid" :class="{ two: form.kind==='embedding' }"><label v-for="p in shownPriceFields" :key="p.key"><span>{{ p.label }}</span><el-input-number v-model="form[p.key]" :min="0" :precision="4" :step="0.1" :controls="false" placeholder="未设置" /></label></div><small class="form-tip">按实际付的价格填写。成本 = 已记录的用量 × 当前价格，改价后历史成本会一起按新价格重算。</small></el-form-item><template v-if="form.kind==='chat'"><el-form-item label="模型内置联网搜索"><el-select v-model="form.webSearchMode"><el-option label="关闭" value="disabled" /><el-option label="Responses API（/responses + web_search，推荐）" value="responses" /><el-option label="Qwen / DashScope（enable_search）" value="qwen" /><el-option label="Chat Completions（web_search_options）" value="openai" /><el-option label="自定义参数" value="custom" /></el-select><small class="form-tip">Responses 模式会调用 /v1/responses，并发送 tools: [{ type: 'web_search' }]。对话测试和机器人回答使用同一配置。</small></el-form-item><el-form-item label="额外请求参数 JSON"><el-input v-model="extraBodyText" type="textarea" :rows="4" placeholder='例如：{"temperature":0.2}' /><small class="form-tip">可留空。思考等级由上方设置统一生成，核心请求字段不会被覆盖。</small></el-form-item></template></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存配置</el-button></template></el-dialog>

    <el-dialog v-model="workbenchVisible" title="模型测试工作台" width="720px" class="model-workbench">
      <template v-if="testingModel"><div class="workbench-model"><span class="entity-icon purple"><el-icon><MagicStick /></el-icon></span><div><strong>{{ testingModel.name }}</strong><span>{{ testingModel.model }} · {{ testingModel.kind === 'chat' ? '对话' : testingModel.kind === 'image' ? '生图' : 'Embedding' }}</span></div></div><el-alert :title="`请求 endpoint：${testEndpoint}`" type="info" :closable="false" show-icon class="endpoint-alert" />
      <el-form label-position="top"><el-form-item v-if="testingModel.kind === 'chat'" label="System Prompt（可选）"><el-input v-model="testForm.systemPrompt" type="textarea" :rows="2" placeholder="例如：你是一名简洁、准确的客服助手" /></el-form-item><el-form-item :label="testingModel.kind === 'chat' ? '用户消息' : testingModel.kind === 'image' ? '画面描述（测试会真实生成一张图，可能产生费用）' : '测试文本'"><el-input v-model="testForm.input" type="textarea" :rows="4" :placeholder="testingModel.kind === 'chat' ? '输入要发送给模型的消息' : '输入需要生成向量的文本'" /></el-form-item><el-button type="primary" :loading="testing" :disabled="!testForm.input.trim()" @click="runTest">运行测试</el-button></el-form>
      <el-alert v-if="testError" title="测试失败" type="error" :closable="false" show-icon class="test-error"><template #default><pre>{{ testError }}</pre><el-button size="small" :icon="CopyDocument" @click="copyText(testError)">复制错误</el-button></template></el-alert>
      <section v-if="testResult" class="workbench-result"><div class="result-heading"><h3>测试结果 · {{ testResult.model }}</h3><StatusBadge status="success" text="请求成功" /></div><template v-if="testResult.kind === 'chat'"><div class="result-output">{{ testResult.content }}</div><div class="result-stats"><div><span>耗时</span><strong>{{ testResult.latencyMs }}ms</strong></div><div><span>输入 Token</span><strong>{{ testResult.inputTokens }}</strong></div><div><span>输出 Token</span><strong>{{ testResult.outputTokens }}</strong></div></div></template><template v-else-if="testResult.kind === 'image'"><el-image v-if="testResult.imageUrl" :src="testResult.imageUrl" :preview-src-list="[testResult.imageUrl]" fit="contain" class="image-result" /><div class="result-stats"><div><span>耗时</span><strong>{{ testResult.latencyMs }}ms</strong></div></div></template><template v-else><div class="result-stats"><div><span>耗时</span><strong>{{ testResult.latencyMs }}ms</strong></div><div><span>向量维度</span><strong>{{ testResult.dimensions }}</strong></div><div><span>预览项数</span><strong>{{ Math.min(12, testResult.vectorPreview.length) }}</strong></div></div><pre class="vector-preview">[{{ testResult.vectorPreview.slice(0, 12).map(value => Number(value).toFixed(6)).join(', ') }}{{ testResult.vectorPreview.length > 12 ? ', …' : '' }}]</pre></template></section></template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { useAdminEvents } from '@/composables/useAdminEvents'
import { computed, onMounted, reactive, ref } from 'vue'
import { ChatDotSquare, Coin, CopyDocument, Cpu, MagicStick, Picture as PictureIcon, Plus, VideoPlay } from '@element-plus/icons-vue'
import EmptyState from '@/components/EmptyState.vue'
import { ElMessage } from 'element-plus'
import { api, sanitizeServiceError } from '@/api'
import PageHeader from '@/components/PageHeader.vue'
import StatusBadge from '@/components/StatusBadge.vue'
import type { ModelProfile, ModelProxy, ModelTestResult } from '@/types'

const models=ref<ModelProfile[]>([]),dialog=ref(false),apiKey=ref(''),extraBodyText=ref(''),workbenchVisible=ref(false),testing=ref(false),testingModel=ref<ModelProfile>(),testResult=ref<ModelTestResult>(),testError=ref('')
const form=reactive<Partial<ModelProfile>>({});
type PriceKey='inputPricePerMillion'|'outputPricePerMillion'|'cacheReadPricePerMillion'|'cacheWritePricePerMillion'
const priceFields:Array<{key:PriceKey;label:string}>=[{key:'inputPricePerMillion',label:'输入'},{key:'outputPricePerMillion',label:'输出'},{key:'cacheReadPricePerMillion',label:'缓存读取'},{key:'cacheWritePricePerMillion',label:'缓存写入'}]
const shownPriceFields=computed(()=>form.kind==='embedding'?priceFields.slice(0,2):priceFields)
function hasPrice(m:ModelProfile){return m.kind==='image'?m.pricePerImage!=null:m.inputPricePerMillion!=null||m.outputPricePerMillion!=null}
function priceText(m:ModelProfile){if(!hasPrice(m))return '未设置';if(m.kind==='image')return `¥${m.pricePerImage} / 张`;const f=(v?:number|null)=>v==null?'—':'¥'+v;return `${f(m.inputPricePerMillion)} / ${f(m.outputPricePerMillion)}`}
const groups=computed(()=>[{kind:'chat' as const,title:'对话模型',hint:'用来生成回复',empty:'至少需要一个对话模型，机器人才能回复消息。',items:models.value.filter(m=>m.kind==='chat')},{kind:'embedding' as const,title:'Embedding 模型',hint:'用来给知识库建索引、检索相关内容',empty:'知识库需要 Embedding 模型才能建索引。',items:models.value.filter(m=>m.kind==='embedding')},{kind:'image' as const,title:'生图模型',hint:'“生成图片”技能使用，在每个 AI 客服里选择用哪一个',empty:'添加后，到 AI 客服的“生图模型”里选择。',items:models.value.filter(m=>m.kind==='image')}]);const testForm=reactive({input:'',systemPrompt:''});const testEndpoint=computed(()=>{if(!testingModel.value)return '';const base=testingModel.value.baseUrl.replace(/\/$/,'');if(testingModel.value.kind==='embedding')return `${base}/embeddings`;if(testingModel.value.kind==='image')return `${base}/images/generations`;return `${base}/${testingModel.value.webSearchMode==='responses'?'responses':'chat/completions'}`})
const proxies=ref<ModelProxy[]>([])
const proxyChoice=computed({get:()=>form.proxyId||'direct',set:(v:string)=>{form.proxyId=v==='direct'?null:v}})
function proxyName(id?:string|null){if(!id)return '直连';return proxies.value.find(p=>p.id===id)?.name||'代理已失效'}
onMounted(load);async function load(){const [list,proxyList]=await Promise.allSettled([api.models.list(),api.system.proxies.list()]);if(list.status==='fulfilled')models.value=list.value;else ElMessage.error(list.reason instanceof Error?list.reason.message:'模型读取失败');if(proxyList.status==='fulfilled')proxies.value=proxyList.value};function searchModeText(mode:ModelProfile['webSearchMode']){return ({disabled:'关闭',responses:'Responses Web Search',qwen:'Qwen 内置搜索',openai:'Chat Completions Web Search',custom:'自定义参数'} as Record<string,string>)[mode]||'关闭'};function reasoningText(level:ModelProfile['reasoningEffort']){return ({default:'模型默认',none:'关闭',minimal:'最小',low:'低',medium:'中',high:'高'} as Record<string,string>)[level]||'模型默认'};function openCreate(kind:'chat'|'embedding'|'image'='chat'){Object.assign(form,{id:'',name:'',kind,provider:'OpenAI Compatible',model:kind==='image'?'gpt-image-2.6-flare':'',baseUrl:'',dimension:1024,status:'online',webSearchMode:'disabled',reasoningEffort:'default',extraBody:{},inputPricePerMillion:null,outputPricePerMillion:null,cacheReadPricePerMillion:null,cacheWritePricePerMillion:null,pricePerImage:null,proxyId:null});apiKey.value='';extraBodyText.value='';dialog.value=true};function edit(m:ModelProfile){Object.assign(form,m);apiKey.value='';extraBodyText.value=Object.keys(m.extraBody||{}).length?JSON.stringify(m.extraBody,null,2):'';dialog.value=true};async function save(){try{form.extraBody=extraBodyText.value.trim()?JSON.parse(extraBodyText.value):{}}catch{ElMessage.error('额外请求参数必须是有效的 JSON 对象');return}if(Array.isArray(form.extraBody)||form.extraBody===null||typeof form.extraBody!=='object'){ElMessage.error('额外请求参数必须是 JSON 对象');return}await api.models.save(form,apiKey.value);await load();dialog.value=false;ElMessage.success('模型配置已保存')}
function openWorkbench(model:ModelProfile){testingModel.value=model;testForm.input=model.kind==='chat'?'请用一句话介绍你自己。':model.kind==='image'?'一只坐在窗台上的橘猫，午后阳光':'这是一段用于测试向量模型的文本。';testForm.systemPrompt='';testResult.value=undefined;testError.value='';workbenchVisible.value=true}
async function runTest(){if(!testingModel.value||!testForm.input.trim())return;testing.value=true;testResult.value=undefined;testError.value='';try{const result=await api.models.test(testingModel.value.id,{input:testForm.input.trim(),systemPrompt:testingModel.value.kind==='chat'&&testForm.systemPrompt.trim()?testForm.systemPrompt.trim():undefined});testResult.value=result;testingModel.value.latency=result.latencyMs;testingModel.value.status='online'}catch(error){testingModel.value.status='warning';testError.value=sanitizeServiceError(error instanceof Error?error.message:'模型测试失败')||'模型测试失败'}finally{testing.value=false}}
async function copyText(value:string){await navigator.clipboard?.writeText(value);ElMessage.success('错误信息已复制')}
useAdminEvents(['model_profiles','model_proxies'], load)
</script>

<style scoped>
.price-item :deep(.el-form-item__content) { display: block; }
.proxy-pill { margin-left: 6px; vertical-align: 1px; }
.option-sub { margin-left: 8px; color: var(--muted); font-size: 12px; }
.price-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; width: 100%; }
.price-grid label { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.price-grid span { color: var(--muted); font-size: 12px; }
.price-grid .el-input-number { width: 100%; }
.price-grid.two { grid-template-columns: repeat(2, minmax(0, 1fr)); max-width: 50%; }
.price-single { width: 200px; }
.entity-facts strong.unset { color: var(--muted); font-weight: 400; }
@media (max-width: 640px) { .price-grid { grid-template-columns: 1fr 1fr; } }
.image-result { display: block; width: 100%; max-height: 360px; margin-bottom: 12px; border-radius: 8px; background: var(--surface-2); }
</style>
